#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

/* Allocate a 2‑D boolean table with the given dimensions. */
static bool **alloc_table(size_t rows, size_t cols)
{
    bool **tbl = malloc(rows * sizeof(bool *));
    if (!tbl) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < rows; ++i) {
        tbl[i] = calloc(cols, sizeof(bool));
        if (!tbl[i]) {
            perror("calloc");
            exit(EXIT_FAILURE);
        }
    }
    return tbl;
}

/* Free a table allocated with alloc_table. */
static void free_table(bool **tbl, size_t rows)
{
    for (size_t i = 0; i < rows; ++i)
        free(tbl[i]);
    free(tbl);
}

/* Returns true if pattern matches text according to the wildcard rules. */
static bool wildcard_match(const char *pattern, const char *text)
{
    size_t p_len = strlen(pattern);
    size_t t_len = strlen(text);

    bool **dp = alloc_table(p_len + 1, t_len + 1);
    dp[0][0] = true;                     /* empty matches empty */

    /* First column: pattern against empty text */
    for (size_t i = 1; i <= p_len; ++i) {
        dp[i][0] = (pattern[i - 1] == '*') ? dp[i - 1][0] : false;
    }

    /* Fill the rest of the table */
    for (size_t i = 1; i <= p_len; ++i) {
        for (size_t j = 1; j <= t_len; ++j) {
            char pc = pattern[i - 1];
            char tc = text[j - 1];

            if (pc == '*')
                dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
            else if (pc == '?' || pc == tc)
                dp[i][j] = dp[i - 1][j - 1];
            else
                dp[i][j] = false;
        }
    }

    bool result = dp[p_len][t_len];
    free_table(dp, p_len + 1);
    return result;
}

int main(int argc, char *argv[])
{
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    const char *pattern = argv[1];
    const char *text    = argv[2];

    if (wildcard_match(pattern, text))
        puts("MATCH");
    else
        puts("NO_MATCH");

    return 0;
}
